import{_ as i,C as s,o as n,c as r,a2 as t,E as o}from"./chunks/framework.CHjbm2Wd.js";const f=JSON.parse('{"title":"V&V for flight software","description":"Requirements, traceability, coverage, independent test, and the evidence a reviewer expects.","frontmatter":{"title":"V&V for flight software","description":"Requirements, traceability, coverage, independent test, and the evidence a reviewer expects."},"headers":[],"relativePath":"test/verification.md","filePath":"test/verification.md","lastUpdated":1792993690000}'),l={name:"test/verification.md"};function d(c,e,h,u,p,g){const a=s("Quiz");return n(),r("div",null,[e[0]||(e[0]=t(`<h1 id="v-v-for-flight-software" tabindex="-1">V&amp;V for flight software <a class="header-anchor" href="#v-v-for-flight-software" aria-label="Permalink to &quot;V&amp;V for flight software&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Why this matters</p><p>For a one-shot landing, “it worked in the sim” is not evidence. Verification and validation (V&amp;V) is how you show that the software was built correctly, that it does the right thing, and that you know where the limits are. It is also a core job responsibility in the roles you are targeting.</p></div><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Distinguish verification from validation and explain IV&amp;V.</li><li>Write a testable requirement and trace it to a test.</li><li>Choose test levels: unit, integration, system, acceptance.</li><li>Select coverage metrics and explain their limits.</li><li>Design nominal, off-nominal, boundary, and fault-injection tests.</li><li>Assemble an evidence package a reviewer can audit.</li></ul><h2 id="definitions-that-matter" tabindex="-1">Definitions that matter <a class="header-anchor" href="#definitions-that-matter" aria-label="Permalink to &quot;Definitions that matter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Question</th><th>Example</th></tr></thead><tbody><tr><td><strong>Verification</strong></td><td>Did we build the product right?</td><td>Does the guidance module meet its interface spec?</td></tr><tr><td><strong>Validation</strong></td><td>Did we build the right product?</td><td>Does the descent guidance land the vehicle within the requirement?</td></tr><tr><td><strong>IV&amp;V</strong></td><td>Independent verification and validation</td><td>A separate team runs the tests and reviews the evidence</td></tr><tr><td><strong>V&amp;V</strong></td><td>The combined process</td><td>Requirements, reviews, analysis, tests, and evidence</td></tr></tbody></table><p>Verification is not just testing. It includes analysis, inspection, review, and demonstration. Testing is the part that produces the most visible evidence.</p><h2 id="requirements-you-can-test" tabindex="-1">Requirements you can test <a class="header-anchor" href="#requirements-you-can-test" aria-label="Permalink to &quot;Requirements you can test&quot;">​</a></h2><p>A good requirement is:</p><ul><li><strong>necessary</strong> — it addresses a real need,</li><li><strong>unambiguous</strong> — one interpretation,</li><li><strong>complete</strong> — includes conditions and constraints,</li><li><strong>consistent</strong> — no conflict with another requirement,</li><li><strong>verifiable</strong> — a method exists,</li><li><strong>traceable</strong> — linked to a source and a test.</li></ul><p>Bad: “The software shall land the vehicle safely.”</p><p>Better: “The descent guidance shall command a touchdown vertical speed magnitude no greater than 1.5 m/s for all Monte Carlo cases in the approved dispersion set, with 99% confidence.”</p><p>The second one tells you what to simulate, what to measure, and how to decide pass/fail.</p><h2 id="traceability" tabindex="-1">Traceability <a class="header-anchor" href="#traceability" aria-label="Permalink to &quot;Traceability&quot;">​</a></h2><p>A traceability matrix links:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stakeholder need → system requirement → software requirement → design → code → test → result</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>For a small project, a spreadsheet is fine. The important properties:</p><ul><li>every requirement has at least one test,</li><li>every test maps to a requirement (or is explicitly exploratory),</li><li>every result has a configuration/version,</li><li>every change updates the links.</li></ul><p>If a requirement has no test, it is a wish. If a test has no requirement, you do not know why it exists.</p><h2 id="test-levels" tabindex="-1">Test levels <a class="header-anchor" href="#test-levels" aria-label="Permalink to &quot;Test levels&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>What is tested</th><th>Example</th></tr></thead><tbody><tr><td><strong>Unit</strong></td><td>One function/class in isolation</td><td>Quaternion normalization, frame transform</td></tr><tr><td><strong>Integration</strong></td><td>Interfaces between modules</td><td>Nav → guidance → control data flow</td></tr><tr><td><strong>System</strong></td><td>The flight software plus plant/sensors</td><td>Closed-loop descent</td></tr><tr><td><strong>Acceptance</strong></td><td>The delivered system against user needs</td><td>Mission scenario, Monte Carlo, HIL</td></tr><tr><td><strong>Regression</strong></td><td>Previously working behavior after a change</td><td>Full suite on every commit</td></tr></tbody></table><p>For flight software, add:</p><ul><li><strong>timing tests:</strong> worst-case execution, jitter, deadline overrun,</li><li><strong>memory tests:</strong> stack high-water, heap usage (ideally zero), static allocation,</li><li><strong>fault-injection tests:</strong> stale sensor, bad checksum, watchdog reset, mode race,</li><li><strong>interface tests:</strong> packet layout, endianness, sequence, timeout,</li><li><strong>configuration tests:</strong> build from a clean tag, correct tables, correct constants.</li></ul><h2 id="coverage" tabindex="-1">Coverage <a class="header-anchor" href="#coverage" aria-label="Permalink to &quot;Coverage&quot;">​</a></h2><p>Common metrics:</p><ul><li><strong>Statement coverage:</strong> was the line executed?</li><li><strong>Branch/decision coverage:</strong> was each branch taken?</li><li><strong>MC/DC:</strong> did each condition independently affect the decision?</li><li><strong>Requirements coverage:</strong> is every requirement tested?</li><li><strong>Interface coverage:</strong> is every message/command exercised?</li></ul><p>Coverage is necessary but not sufficient. A test can execute a line and assert nothing. A requirement can be “covered” by a test that does not check the right behavior. Pair coverage with meaningful assertions and review.</p><h2 id="flight-software-test-design" tabindex="-1">Flight-software test design <a class="header-anchor" href="#flight-software-test-design" aria-label="Permalink to &quot;Flight-software test design&quot;">​</a></h2><p>Use a mix:</p><ul><li><strong>Nominal:</strong> the expected trajectory, sensors, and commands.</li><li><strong>Off-nominal:</strong> sensor dropout, bias, saturation, bad command, mode transition.</li><li><strong>Boundary:</strong> minimum/maximum altitude, throttle, rate, time, memory.</li><li><strong>Fault injection:</strong> stuck sensor, corrupt packet, watchdog, reset, power glitch.</li><li><strong>Stress:</strong> high rate, queue overflow, CPU load, long duration.</li><li><strong>Monte Carlo:</strong> dispersions and statistical requirements.</li><li><strong>Regression:</strong> every fixed bug gets a test.</li></ul><p>A useful format:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ID: T-GUID-014</span></span>
<span class="line"><span>Requirement: REQ-GUID-007</span></span>
<span class="line"><span>Objective: Verify terminal descent commands a vertical speed &lt;= 1.5 m/s at touchdown</span></span>
<span class="line"><span>Setup: 6DOF SIL, 100 dispersed cases, sensor noise enabled</span></span>
<span class="line"><span>Inputs: seed 20261026, mass/thrust/IMU dispersions per MC plan</span></span>
<span class="line"><span>Pass criteria: 99th percentile |v_z| &lt;= 1.5 m/s; no crashes; fuel reserve &gt;= 2%</span></span>
<span class="line"><span>Result: PASS, 99th percentile 1.12 m/s</span></span>
<span class="line"><span>Evidence: report.html, run log, model version, commit hash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="npr-7150-2-in-one-paragraph" tabindex="-1">NPR 7150.2 in one paragraph <a class="header-anchor" href="#npr-7150-2-in-one-paragraph" aria-label="Permalink to &quot;NPR 7150.2 in one paragraph&quot;">​</a></h2><p>NASA NPR 7150.2 defines software engineering requirements for NASA software, including software classes A–E based on criticality. It covers lifecycle processes, requirements, design, implementation, testing, verification, validation, configuration management, quality assurance, safety, and security. Commercial lunar landers are not automatically bound by it, but the vocabulary and evidence expectations are widely used. Do not claim compliance unless you have tailored and documented it. The <a href="./../flight/npr-7150.html">NPR 7150.2 page</a> goes deeper.</p><h2 id="the-evidence-package" tabindex="-1">The evidence package <a class="header-anchor" href="#the-evidence-package" aria-label="Permalink to &quot;The evidence package&quot;">​</a></h2><p>A reviewer should be able to answer:</p><ul><li>What was the requirement?</li><li>What version of the software/model was tested?</li><li>What test was run, with what inputs and environment?</li><li>What was the pass/fail criterion?</li><li>What was the result?</li><li>Who reviewed it?</li><li>What changed since the last run?</li></ul><p>Minimum artifacts:</p><ul><li>requirements and trace matrix,</li><li>test plan and test cases,</li><li>test logs and reports,</li><li>coverage and static-analysis reports,</li><li>configuration/build record,</li><li>problem reports and dispositions,</li><li>review records.</li></ul><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><ul><li><strong>Testing the model, not the flight build.</strong> The generated code or target build can differ.</li><li><strong>Coverage theater.</strong> 100% statement coverage with weak assertions.</li><li><strong>No negative tests.</strong> Only the happy path is tested.</li><li><strong>Unversioned test data.</strong> The result cannot be reproduced.</li><li><strong>Flaky tests accepted.</strong> A test that passes sometimes is not evidence.</li><li><strong>No timing tests.</strong> Functional correctness at the wrong rate is still a failure.</li><li><strong>No fault injection.</strong> The fault paths are the ones that matter in flight.</li><li><strong>Overclaiming compliance.</strong> “NPR 7150.2 compliant” without a tailored matrix and audit evidence.</li></ul><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ol><li>Write five requirements for your descent sim: one performance, one interface, one fault, one timing, one safety.</li><li>For each, write a test case with a pass/fail criterion and the evidence it produces.</li><li>Build a traceability matrix from requirement to test to result.</li><li>Add a fault-injection test for a stale nav state and one for a corrupt command packet.</li><li>Run the suite from a clean checkout and archive the report with the commit hash.</li></ol>`,43)),o(a,{question:"A test suite reports 100% statement coverage. What is the strongest conclusion?",options:"The software is correct|Every statement was executed, but the assertions may still be weak and requirements may be untested|The software is safe for flight|The requirements are complete",answer:"1",explanation:"Coverage measures execution, not correctness. You still need meaningful assertions, requirements coverage, boundary cases, and fault injection."}),e[1]||(e[1]=t('<h2 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h2><ul><li><a href="https://nodis3.gsfc.nasa.gov/displayDir.cfm?t=NPR&amp;c=7150&amp;s=2" target="_blank" rel="noreferrer">NPR 7150.2</a> — NASA software engineering requirements.</li><li><a href="https://standards.nasa.gov/" target="_blank" rel="noreferrer">NASA-STD-8739.8</a> — software assurance.</li><li><a href="https://swehb.nasa.gov/" target="_blank" rel="noreferrer">NASA Software Engineering Handbook</a> — practical guidance.</li><li><a href="https://www.rtca.org/" target="_blank" rel="noreferrer">DO-178C</a> — the airborne analogue, useful for assurance concepts.</li></ul><p>Next: <a href="./sil-hil.html">SIL &amp; HIL</a>.</p>',3))])}const b=i(l,[["render",d]]);export{f as __pageData,b as default};
